     /* this box-sizing is super-critical. It makes sure that padding is never caluclated on the */
/*OUTSIDE of of ALL layuot DIVs in the entire website. Without this entry , DIVs escape 100% widths */
* {box-sizing: border-box;}

/* FONTS */
@import url('https://fonts.googleapis.com/css2?family=Cabin&display=swap'); /* Cabin Google Font */ 
@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@200;300;400;500;600;700;900&display=swap'); /* Montserrat Google Font */
@import url('https://fonts.googleapis.com/css2?family=Lato:wght@300;400;700;900&display=swap'); /* Lato Google Font */

/* The root HTML tag is where the root font size (rem) is set for the entire website. */
html {
    box-sizing: border-box;
    color: #333;
    height: auto;
    font-size: 16px;
}
body {
    background: #FFF;
    font-family: 'Roboto', sans-serif;
    display: block;
    margin: 0;
    width: 100%;
    max-width:100vw;
    height: 100%;
    box-sizing: border-box;
    font-smooth: auto;
    font-size: 16px;
}
img {max-width:90vw;}

/* Overall Wrapper */
body #evo_overall_content_wrapper {
    min-height: 100%;
    display: block;
    width:100%;
    max-width: 100vw;
}
body #evo_overall_content_wrapper.evo_menu_mobile_visible_content_wrapper {
    height:100%;
    width:100%;
    margin:0;
    padding:0;
} /* evo common has y scrolling on the mobile menu/page - this fixes that */


/* FontAwesome DuoTone Colors */ 
.fad {
    --fa-primary-color: #f8f8ff; 
    --fa-secondary-color: #eeeeee; /* brunswick green */
    --fa-primary-opacity: 1; /* make icon color opaque */
    --fa-secondary-opacity 1; /* make icon color opaque */
}

/* ALERT SCROLLER */
.evo_param_grid_alert_scroll {
    z-index:5000;
    background-color: #003A70; !important;
}
/* ALERT SCROLLER - END */

/* HEADER - BEGIN */
#evo_header_wrapper {
    background: #033859;
    position: relative;
    z-index: 50000 !important;
    width: 100%;
    max-width:100vw;
    position: relative;
    top: 0px;
    color:#fff;
}
#evo_header {
    height: 180px;
    max-width:1400px;
    margin:0 auto;
}
#evo_header .title {
    box-sizing: border-box;
    max-width: 100%;
    width: 100%;
}
#evo_header #evo_title_logo_div {
    width: 100%;
    box-sizing: border-box;
    min-width: 90vw;
}
#evo_header .evo_title_prefix {
    Display:none;
    position: absolute;
    color: #f1f1f1;
    font-size: 24px;
    top: 20px;
    margin-left: 198px;
    font-family: 'Crimson Text', serif;
}
#evo_header .evo_title_main {
    position: absolute;
    color: #f1f1f1;
    font-size: 3rem;
    top: 36px;
    margin-left: 220px;
    font-family: 'Crimson Text', serif;
}
#evo_header .evo_title_suffix {
    position: absolute;
    color: #f1f1f1;
    font-size: 1.5rem;
    top: 90px;
    margin-left: 338px;
    font-family: 'Crimson Text', serif;
    letter-spacing: 13px;
    text-transform: uppercase;
}
@media (max-width: 960px) {
   #evo_header .evo_title_prefix {
        position: absolute;
        color: #fff;
        font-size: 2rem;
        top: 19px;
        margin-left: 110px;
        font-family: 'Crimson Text', serif;
    }
    #evo_header .evo_title_main {
        position: absolute;
        color: #fff;
        font-size: 2rem;
        top: 31px;
        margin-left: 110px;
        font-family: 'Crimson Text', serif;
    }
    #evo_header .evo_title_suffix {
        position: absolute;
        color: #fff;
        font-size: 1.2rem;
        top: 70px;
        margin-left: 190px;
        font-family: 'Crimson Text', serif;
        letter-spacing: 6px;
        text-transform: uppercase;
    }
}
@media (max-width: 320px) {
   #evo_header .evo_title_prefix {
        position: absolute;
        color: #fff;
        font-size: 2rem;
        top: 19px;
        margin-left: 110px;
        font-family: 'Crimson Text', serif;
    }
    #evo_header .evo_title_main {
        position: absolute;
        color: #fff;
        font-size: 1.5rem;
        top: 40px;
        margin-left: 110px;
        font-family: 'Crimson Text', serif;
    }
    #evo_header .evo_title_suffix {
        position: absolute;
        color: #fff;
        font-size: 1.1rem;
        top: 65px;
        margin-left: 170px;
        font-family: 'Crimson Text', serif;
        letter-spacing: 6px;
        text-transform: uppercase;
    }
}

/* Header search - begin */
#evo_search {
	position: relative;
	top: 60px;
	float: right;
}
#evo_search > form > div > span {
	position: absolute;
	right: 0px;
	cursor: pointer;
	display: none;
}
#evo_search input {
    position:absolute;
    right:0;
	font-size: 14px;
    border-radius: 7px;
    border: solid 1px #999;
    height: 25px;
    width: 200px;
    padding-left: 20px;
}
.evo_form_submit {
    float: right;
}
#evo_search button {
	background-color: transparent;
	border-width: 0px;
	color: rgba(16, 94, 153, 1.0);
}
#evo_overall_content_wrapper .evo_search_input {
	width: 75%;
}
#evo_overall_content_wrapper .evo_search_button {
	padding: 5px;
}
@media (max-width: 960px) {
    body input#search-input-query.form-control {
	position: absolute;
	top: 0px;
	right: 100px;
	width: 150px;
    }
    /* shorten search box for phones */
    input#search-input-query.form-control {
	width: 150px;
    }
}
@media (max-width: 414px) {
    body input#search-input-query.form-control {
    position: absolute;
    top: 0;
    right: 32px;
    width: 150px;
    }
}
@media (max-width: 375px) {
    body input#search-input-query.form-control {
    position: absolute;
    top: 0;
    right: 32px;
    width: 150px;
    }
}
@media (max-width: 320px) {
    body input#search-input-query.form-control {
        top:0;
        right:30px;
    }
}
/* Header Search - end */

/* Top Action Menu */
#evo_top_action {
    position:absolute;
    right:200px;
    top:15px;
}
#evo_top_action ul {
    margin: 0;
}
#evo_top_action li {
    list-style: none;
    display: inline;
    margin-top: 5px;
    
}
#evo_top_action a {
    color: #fff;
    margin-left:2rem;
    text-decoration:none;
}
#evo_top_action a:hover {
    text-decoration:underline;
}
@media (max-width:1440px) {
    
}
@media (max-width: 800px) {
    body #evo_top_action {
        position:absolute;
        right:100px;
        top:15px;
    }
}
@media (max-width: 768px) {
    body #evo_top_action {
        position:absolute;
        top:15px;
        right:100px;
    }
}
@media (max-width: 438px) {
    body #evo_top_action {
        position:absolute;
        top:9px;
        left:150px;
        width:100%;
    }
    body #evo_top_action a {
        margin-left:4px;
        font-size:.8rem;
    }
}
@media (max-width: 375px) {
    body #evo_top_action {
        position:absolute;
        top:5px;
        left:150px;
        width:100%;
    }
}
@media (max-width: 320px) {
    body #evo_top_action {
        position:absolute;
        top:9px;
        left:-25px;
        width:100%;
    }
    body #evo_top_action a {
        margin-left:4px;
        font-size:.8rem;
    }
}

/* Mobile Menu - Begin */
.evo_menu_mobile_visible {
    left: 0px !important;
    transition: left 0.5s ease !important;
}
.evo_menu_mobile_visible_content_wrapper {
    margin-left: 100%;
    transition: margin-left 0.5s ease !important;
}
/* Mobile Menu - End */

/* Social Action Menu - Begin */
#evo_social_action {
    position: relative;
    top: 18px;
    float:right;
    clear:right;
}
#evo_social_action li {
    display: inline-block;
}
#evo_social_action i {
    font-size: 2rem;
    color: #333;
}
@media (max-width: 540px) {
    #evo_social_action {
        top:77px;
        right:25px;
    }
}
/* Social Action Menu - End */

/* LOGO & SITE TITLE - BEGIN */
#evo_logo_primary {
    position: absolute;
    height: 160px;
    margin-left: 50px;
    margin-top: 5px;
}
#evo_title_logo span img {
    height: 4em;
    position: absolute;
    margin-top: 1.5em;
    margin-left: 2em;
}
@media (max-width: 320px) {
    #evo_logo_primary {margin-top:32px;}
}
/* LOGO & SITE TITLE - END */

/* MAIN MENU - BEGIN */
.menu_item_title {
    font-style: italic;
    color: #D9C077 !important;
    display:none;
}
#evo_main_menu_wrapper {
    position: absolute;
    z-index: 1000;
    box-sizing: border-box;
    background-color: #112244;
    left:0;
    top:170px;
    width:100%;
    max-width:100vw;
    height:39px;
}
#evo_menu_inner_wrapper {
    max-width:1400px;
    margin:0 auto;
}
body #evo_main_menu {
    z-index: 1000;
    max-width: 1400px;
    position: relative;
    margin:0 auto;
}
#evo_main_menu .evo_menu_heading {
    list-style: none;
    padding-top: 3px;
}
#evo_main_menu .evo_menu_inner_wrapper {
    /* Position the Main Menu Headings */
    box-sizing: border-box;
    max-width: 100%;
}
#evo_main_menu > div > ul {
    display: grid;
    grid-gap: 20px;
    grid-template-columns: repeat(auto-fit, minmax(75px, 1fr));
    background-color: transparent !important;
    max-width: 100%;
    box-sizing: border-box;
    margin-top:0;
}
/* Main Menu Button Font */
#evo_main_menu > div > ul > li > a {
    text-decoration: none;
    text-align: center;
    color: #FFF;
    font-size: 1.2rem;
    font-family: 'cabin', sans-serif;
    position: relative;
    padding: 7px;
    white-space: nowrap;
    display: block;
}
#evo_main_menu > div > ul > li > a:hover {

}
#evo_main_menu li {
    list-style: none !important;
}
/* Main Menu Heading Background Color */
#evo_main_menu > div > ul {
    background: rgba(30, 90, 30, 1.0);
}
/* MEGA MENU PANEL BACKGROUND COLOR & TRANSPARENCY */
body #evo_main_menu.evo_desktop_mode > div > ul > li > ul {
    background: rgba(11, 32, 59, 0.9); 
     -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
    /* display: block !important; */
    opacity:0;
    visibility: hidden; /* Do not display the menu under any headings not being hovered over */
    z-index:10000;
    transition: visibility 0s, opacity 0.8s linear;
}
body #evo_main_menu.evo_desktop_mode > div > ul > li:hover > ul {
    /* Main Menu Dropdown Background Color */
    visibility: visible; /* Display the menu under any headings being hovered over */
    opacity:1;
    display: block !important;
    position: absolute;
    transition: visibility 0.5s, opacity 0.8s linear;
     -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
/* to make mega menu full-width to widht of main menu */
body ul.evo_menu_dropdown { right:0 !important;}
#evo_main_menu > div > ul > li > ul.evo_display_block_important {
    display: block !important;
}
#evo_main_menu > div > ul > li > ul span, #evo_main_menu > div > ul > li > ul a {
    /* Align all span and link text to the left in the main menu that is not in the heading */
    text-align: left;
}
#evo_main_menu > div > ul > li > ul > li {padding: 5px;width:100%;} /* the width 100% will fix spacing issues with MS Edge */
#evo_main_menu > div > ul > li > ul > li ul {
    padding: 5px;
}
#evo_main_menu > div > ul > li > ul > li > ul > li {
    margin-left: 10px;
}
#evo_main_menu > div > ul > li > ul > li > a {
    /* Main Menu Headings 2 Layers Deep */
    font-size: 1.0rem;
    padding-top: 0px;
    color: #eee;
    text-decoration: none;
    font-weight: 700;
    text-transform: uppercase;
    border-bottom: 1px solid rgba(255, 255, 255, .15);
}
#evo_main_menu > div > ul > li > ul > li > ul > li > a {
    /* Main Menu 3 Layers Deep */
    font-size: 0.95rem;
    padding-top: 0px;
    color: #fff;
    text-decoration: none;
}
#evo_main_menu > div > ul > li > ul > li > ul > li > ul > li > a {
    /* Main Menu 4 Layers Deep */
    font-size: 0.90rem;
    padding-top: 0px;
    color: #fff;
    text-decoration: none;
}
#evo_main_menu > div > ul > li > ul > li > ul > li > ul > li > ul > li > a {
    /* Main Menu 5 Layers Deep */
    font-size: 0.85rem;
    padding-top: 0px;
    color: #fff;
    text-decoration: none;
}
#evo_main_menu > div > ul > li > ul > li > ul > li > ul > li > ul > li > ul > li > a {
    /* Main Menu 6 Layers Deep */
    font-size: 0.80rem;
    padding-top: 0px;
    color: #fff;
    text-decoration: none;
}
#evo_main_menu > div > ul > li > ul > li > ul > li > ul > li > ul > li > ul > li > ul > li > a {
    /* Main Menu 7 Layers Deep */
    display: none;
}
#evo_menu_float a {
    text-decoration: none;
    color: #fff;
}
@media (max-width: 1280px) {
    #evo_main_menu_wrapper {
        padding-left: 40px;
        padding-right: 40px;
    }
    #evo_main_menu > div > ul > li > a, #evo_main_menu > div > ul > li > span {
        font-size: 1.5em;
    }
    #evo_main_menu .evo_menu_inner_wrapper {
        margin-right: 10px;
    }
    #evo_main_menu > div > ul {
        grid-gap: 30px;
        margin:0 auto;
    } /* space the main menu items and move them left at this screen size so there is room between long titles */
    #evo_main_menu > div > ul > li > a, #evo_main_menu > div > ul > li > span {
        font-size: 0.8rem;
    }
    /* Second level main menu links in mobile */
    #evo_main_menu > div > ul > li > ul > li > a, #evo_main_menu > div > ul > li > ul > li > span {
        font-size: 1rem;
        text-transform:none;
        font-weight:400;
    }
}
@media (max-width: 960px) {
    /* main menu */
    body #evo_main_menu_wrapper {
        left: -100%;
        transition: left 0.5s ease !important;
        position: fixed;
        top: 0px;
        width: 100%;
        height: 100vh;
        overflow-y: auto;
        margin-top: 0px;
        background: #033859;
        padding-left: 0px;
        padding-right: 0px;
        margin-left: 0px;
        padding-top: 60px;
        max-width: 100%;
    }
    #evo_main_menu {
        padding-right: 30px;
        margin-lefT:0;
    }
    body #evo_main_menu > div > ul > li > a {
        font-size:1.25rem !important;
        text-decoration: none;
        border-bottom: 1px solid rgba(255, 255, 255, .25);
    }
    body #evo_main_menu > div > ul > li > ul > li > a {
        font-size:1.2rem !important;
        text-decoration: none;
        padding-left:10px;
        border-bottom: none;
    }
    body #evo_main_menu > div > ul > li > ul > li > ul > li > a {
        text-decoration: none;
        font-size:1.1rem !important;
        padding-left:10px;
        border-bottom: none;
    }
    
    #evo_main_menu > div > ul > li > a, #evo_main_menu > div > ul > li > span {font-size: 1.1em;}
    #evo_main_menu > div > ul > li:nth-child > a, #evo_main_menu > div > ul > li:nth-child > span {transform: unset;}
    #evo_main_menu > div > ul > li > a, #evo_main_menu > div > ul > li > span {font-weight: bold;}
    /* Second Level */
    #evo_main_menu > div > ul > li > ul > li, #evo_main_menu > div > ul > li > ul > li {transition: all 0.5s ease !important;}
    #evo_main_menu > div > ul > li > a, #evo_main_menu > div > ul > li > span {position: relative;}
    body .evo_main_menu_heading_caret {
        left: unset;
        font-size:2rem !important;
    }
    #evo_main_menu .evo_menu_inner_wrapper {transition: top 0.5s ease !important;}
    #evo_main_menu > div > ul > li > ul {height: auto !important;}
    /* MOBILE MENUS - BEGIN */
    /* X to close mobile menu */
    .evo_menu_mobile_visible #evo_grid_main_menu_mobile_toggle_inside_menu_wrapper {
        display: block !important;
        position: absolute;
        right: 40px;
        top: 20px;
        color: #fff;
        cursor: pointer;
        transform: scale(2);
        transition: all 1s ease-in-out;
        z-index:5000;
        }
    .evo_menu_mobile_visible .fa-bars::before {
        content: "\f2d3";
        z-index:200;
        line-height:2rem;
    }
    /* Hamburger Mobile Menu Icon and color */
    #evo_grid_main_menu_mobile_toggle {
        display: block !important;
        position: absolute;
        right: 40px;
        top: 20px;
        color: #fff;
        cursor: pointer;
        transform: scale(2);
        z-index:200;
    } 
    /* MOBILE MENUS - END */
}
@media (max-width: 768px) {
    /* main menu */
    body #evo_main_menu_wrapper {
        left: -100%;
        transition: left 0.5s ease !important;
        position: fixed;
        top: 0px;
        width: 100%;
        max-width:100vw;
        height: 100%;
        background: #033859;
        padding: 0;
        margin: 0;

    }
    body #evo_main_menu {
        padding-right: 30px;
        margin-lefT:0;
        margin-top:30px;
    }
    body #evo_main_menu > div > ul > li > a {
        font-size:1.25rem !important;
        text-decoration: none;
        border-bottom: 1px solid rgba(255, 255, 255, .25);
    }
    body #evo_main_menu > div > ul > li > ul > li > a {
        font-size:1.2rem !important;
        text-decoration: none;
        padding-left:10px;
        border-bottom: none;
    }
    body #evo_main_menu > div > ul > li > ul > li > ul > li > a {
        text-decoration: none;
        font-size:1.1rem !important;
        padding-left:10px;
        border-bottom: none;
    }
    #evo_main_menu > div > ul > li > a, #evo_main_menu > div > ul > li > span {font-size: 1.1em;}
    #evo_main_menu > div > ul > li:nth-child > a, #evo_main_menu > div > ul > li:nth-child > span {transform: unset;}
    #evo_main_menu > div > ul > li > a, #evo_main_menu > div > ul > li > span {font-weight: bold;}
    /* Second Level */
    #evo_main_menu > div > ul > li > ul > li, #evo_main_menu > div > ul > li > ul > li {transition: all 0.5s ease !important;}
    #evo_main_menu > div > ul > li > a, #evo_main_menu > div > ul > li > span {position: relative;}
    body .evo_main_menu_heading_caret {
        left: unset;
        font-size:2rem !important;
    }
    #evo_main_menu .evo_menu_inner_wrapper {transition: top 0.5s ease !important;}
    #evo_main_menu > div > ul > li > ul {height: auto !important;}
    /* MOBILE MENUS - BEGIN */
    /* X to close mobile menu */
    .evo_menu_mobile_visible #evo_grid_main_menu_mobile_toggle_inside_menu_wrapper {
        display: block !important;
        position: absolute;
        right: 40px;
        top: 20px;
        color: #fff;
        cursor: pointer;
        transform: scale(2);
        transition: all 1s ease-in-out;
        z-index:5000;
        }
    .evo_menu_mobile_visible .fa-bars::before {
        content: "\f2d3";
        z-index:200;
        line-height:2rem;
    }
    /* Hamburger Mobile Menu Icon and color */
    #evo_grid_main_menu_mobile_toggle {
        display: block !important;
        position: absolute;
        right: 40px;
        top: 20px;
        color: #fff;
        cursor: pointer;
        transform: scale(2);
        z-index:200;
    } 
    /* MOBILE MENUS - END */
}
@media (max-width: 414px) {
    body #evo_main_menu {
        padding-right:0;
        padding-top:30px;
    }
}
@media (max-width: 320px) {
    body #evo_main_menu {
        padding-right:0;
        padding-top:30px;
    }
    body #evo_main_menu > div > ul > li > a {
        font-size:1.1rem !important;
        }
    body .evo_main_menu_heading_caret {
        
        
    }
    
}
/* MAIN MENU - END */
/* Header End */

/* FOOTER - BEGIN */
body #evo_footer_wrapper {
    width:100%;
    background: #033859;
    }
body #evo_footer {
    background-size: cover;
    background-repeat: no-repeat;
    color: #fff;
    box-sizing: border-box;
    padding: 20px 60px;
    max-width:1200px;
    margin:0 auto;
    background-color: #033859;
}
#evo_footer ul {
    padding: 0;
}
#evo_footer li {
    list-style: none;
}
#evo_footer .footer-box {
    display: grid;
    grid-gap: 50px;
    grid-template-columns: repeat(4, 1fr);
    width: 100%;
    box-sizing: border-box;

}
#evo_footer .footer-box > div {
    box-sizing: border-box;
    padding: 20px;
}
#evo_footer a {
    color: #fff;
    text-decoration: none;
}
#evo_footer a:hover {
    text-decoration: underline;
}
#evo_footer h3 {
    color: #FFF;
    font-size: 20px;
    margin-top: 0;
    font-weight: 700;
}
#evo_footer .address {
    font-size: 14px;
    z-index: 12;
    position: relative;
}
#evo_footer .resources {
    font-size: 14px;
}
#evo_footer .connect {
    font-size: 14px;
}
#evo_footer .site-links {
    font-size: 14px;
}
#evo_link_to_evogov_cms {
    width: 100%;
    text-align: center;
    color: #fff;
    font-size: 0.8em;
}
#evo_logo_secondary {
    position: absolute;
    height: 150px;
}
@media (max-width: 768px) {
    #evo_footer .footer-box {
